import sys
from collections.abc import Sequence

from bubble_sort.core import bubble_sort

DEMO_VALUES = (64, 34, 25, 12, 22, 11, 90)
ParsedValues = list[int] | list[str]

__all__ = ["DEMO_VALUES", "main", "parse_values", "sorted_values"]


def parse_values(arguments: Sequence[str]) -> ParsedValues:
    if not arguments:
        return list(DEMO_VALUES)

    integers = _parse_integer_arguments(arguments)
    if integers is not None:
        return integers

    return list(arguments)


def _parse_integer_arguments(arguments: Sequence[str]) -> list[int] | None:
    try:
        return [int(argument) for argument in arguments]
    except ValueError:
        return None


def sorted_values(arguments: Sequence[str]) -> ParsedValues:
    values = parse_values(arguments)
    bubble_sort(values)
    return values


def main(argv: Sequence[str] | None = None) -> None:
    arguments = sys.argv[1:] if argv is None else argv
    values = sorted_values(arguments)
    print(values)

from bubble_sort.cli import main, parse_values, sorted_values


def test_parse_values_uses_demo_values_when_no_arguments() -> None:
    assert parse_values(()) == [64, 34, 25, 12, 22, 11, 90]


def test_parse_values_keeps_text_arguments() -> None:
    assert parse_values(("pear", "apple", "banana")) == ["pear", "apple", "banana"]


def test_sorted_values_sorts_cli_arguments() -> None:
    assert sorted_values(("5", "1", "3")) == [1, 3, 5]


def test_sorted_values_sorts_text_arguments() -> None:
    assert sorted_values(("pear", "apple", "banana")) == ["apple", "banana", "pear"]


def test_cli_main_prints_sorted_demo_values(capsys) -> None:
    main(())

    assert capsys.readouterr().out == "[11, 12, 22, 25, 34, 64, 90]\n"
